WITH enriched AS (SELECT id, name, email, country, city, segment, signup_date, is_active, credit_limit, age, SUM(age) OVER (PARTITION BY segment ORDER BY age, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_age, NTILE(5) OVER (PARTITION BY country ORDER BY credit_limit, id) AS credit_limit_bucket FROM customers) SELECT DATE_TRUNC('WEEK', signup_date) AS week_start, CASE WHEN age >= 61 THEN 'PREMIUM' ELSE 'STANDARD' END AS age_tier, CASE WHEN credit_limit >= 14000 THEN 'LARGE' ELSE 'SMALL' END AS credit_limit_tier, COUNT_IF(country = 'US') AS us_events, BIT_OR(age) AS age_bit_or, SORT_ARRAY(COLLECT_SET(country)) AS country_list FROM enriched GROUP BY week_start, age_tier, credit_limit_tier ORDER BY credit_limit_tier DESC
